package com.earthtrip.notification.adapter.in.web.api.v1.me.push_devices.by_device_id;import com.earthtrip.notification.application.port.in.NotificationUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/me/push-devices/{deviceId}") class PushDeviceByIdController{private final NotificationUseCase useCase;private final CurrentActor actor;PushDeviceByIdController(NotificationUseCase u,CurrentActor a){useCase=u;actor=a;}@PostMapping @ResponseStatus(HttpStatus.NO_CONTENT)void post(@PathVariable String deviceId,@Valid @RequestBody PushDeviceMutation r){useCase.registerDevice(actor.requireUserId(),deviceId,r.platform(),r.token(),r.appBuild());}@DeleteMapping @ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable String deviceId){useCase.removeDevice(actor.requireUserId(),deviceId);}}
record PushDeviceMutation(@NotBlank String platform,@NotBlank String token,@Positive int appBuild){}
